Generierte Query:
SELECT song_name, song_release_year
FROM singer
WHERE singer_id = (SELECT singer_id FROM singer ORDER BY age ASC LIMIT 1);

SELECT song_name, song_release_year
FROM singer
WHERE age = (SELECT MIN(age) FROM singer);

SELECT T1.major, T1.age
FROM Student AS T1
WHERE T1.stuid NOT IN (SELECT T2.stuid FROM Has_Pet AS T2 JOIN Pets AS T3 ON T2.petid = T3.petid WHERE T3.pettype = 'Cat');

SELECT DISTINCT stuid
FROM Student
WHERE stuid NOT IN (SELECT stuid FROM Has_Pet WHERE petid IN (SELECT petid FROM Pets WHERE pettype = 'Cat'));

SELECT pettype, weight
FROM Pets
WHERE petid = (SELECT petid FROM Pets ORDER BY pet_age ASC LIMIT 1);

SELECT AVG(stuid)
FROM Student
WHERE stuid NOT IN (SELECT stuid FROM Has_Pet);

SELECT DISTINCT model
FROM model_list
WHERE modelid IN (SELECT modelid FROM chip_model WHERE launch_year > 1980);

SELECT DISTINCT model
FROM model_list
WHERE modelid > 1980;

SELECT model
FROM model_list
WHERE modelid IN (SELECT makeid FROM car_names WHERE makeid IN (SELECT id FROM cars_data ORDER BY mpg DESC LIMIT 1));

SELECT model
FROM model_list
WHERE modelid IN (SELECT id FROM cars_data ORDER BY mpg DESC LIMIT 1);

SELECT country_name
FROM countries
WHERE countryid NOT IN (SELECT country FROM car_makers);
